import { useState } from 'react';

const produk = [
  { id: 1, nama: 'Kopi Susu', harga: 15000 },
  { id: 2, nama: 'Teh Melati', harga: 8000 },
  { id: 3, nama: 'Roti Bakar', harga: 12000 },
];

const rupiah = (n) => 'Rp' + n.toLocaleString('id-ID');

function DaftarProduk({ onTambah }) {
  return (
    <div className="produk">
      {produk.map((p) => (
        <button key={p.id} onClick={() => onTambah(p)}>+ {p.nama}</button>
      ))}
    </div>
  );
}

function Keranjang({ isi, onUbah }) {
  const jumlahBarang = isi.reduce((n, b) => n + b.jumlah, 0);
  const total = isi.reduce((t, b) => t + b.harga * b.jumlah, 0);
  if (isi.length === 0) return <p>Keranjang masih kosong</p>;
  return (
    <section>
      <h3>Keranjang ({jumlahBarang} barang)</h3>
      <ul>
        {isi.map((b) => (
          <li key={b.id}>
            {b.nama}{' '}
            <button onClick={() => onUbah(b.id, -1)} aria-label={`Kurangi ${b.nama}`}>−</button>
            {' '}{b.jumlah}{' '}
            <button onClick={() => onUbah(b.id, 1)} aria-label={`Tambah ${b.nama}`}>+</button>
            {' '}{rupiah(b.harga * b.jumlah)}
          </li>
        ))}
      </ul>
      <p><b>Total: {rupiah(total)}</b></p>
    </section>
  );
}

export default function App() {
  const [keranjang, setKeranjang] = useState([]);

  function tambah(p) {
    setKeranjang((isi) =>
      isi.some((b) => b.id === p.id)
        ? isi.map((b) => (b.id === p.id ? { ...b, jumlah: b.jumlah + 1 } : b))
        : [...isi, { ...p, jumlah: 1 }]
    );
  }

  function ubahJumlah(id, selisih) {
    setKeranjang((isi) =>
      isi
        .map((b) => (b.id === id ? { ...b, jumlah: b.jumlah + selisih } : b))
        .filter((b) => b.jumlah > 0)
    );
  }

  return (
    <div>
      <DaftarProduk onTambah={tambah} />
      <Keranjang isi={keranjang} onUbah={ubahJumlah} />
    </div>
  );
}
